const fetchUrl = `${url}?${queryString}`;

try {
  const response = await fetch(fetchUrl, options);

  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }

  const jsonData = await response.json();
  console.log(jsonData);
} catch (error) {
  console.error(error);
}
```

